  final String? error;

  @override
  Component build(BuildContext context) {
    final note = error ?? description;
    return div(classes: 'ash-field', [
      Component.element(
        tag: 'label',
        classes: 'ash-field-label',
        attributes: {'for': id},
        children: [Component.text(label)],
